<script setup>defineProps({title:String,subtitle:String,badge:{type:String,default:'DWS'},accent:{type:String,default:'cyan'},level:{type:Number,default:2},loading:Boolean,empty:Boolean,error:String})</script>
<template><section class="panel" :class="[`accent-${accent}`,`level-${level}`]"><header><div><h2><i></i>{{title}}</h2><p v-if="subtitle">{{subtitle}}</p></div><span class="panel-mark">{{badge}}</span></header><div v-if="loading&&empty" class="state"><span class="loader"></span>正在读取数仓…</div><div v-else-if="error&&empty" class="state error">{{error}}</div><div v-else-if="empty" class="state">暂无数据</div><div v-else class="panel-body"><slot /></div><b class="corner"></b></section></template>
